INSERT INTO POLICY_DOCS (doc_id, title, category, content) VALUES
('P01', 'Vulnerability Remediation Standard', 'Remediation', 'Critical findings must be remediated within 7 days of discovery. High findings within 30 days, Medium within 90 days, and Low within 180 days. Findings on internet-facing assets or with a known exploit are treated one severity level higher for deadline purposes. Remediation is complete only when a follow-up scan confirms the fix.'),
('P02', 'Risk Exception Process', 'Exceptions', 'A remediation exception may be requested when a fix cannot be applied within the deadline. Requests need a business justification, a compensating control, an owner, and an expiry date of no more than 90 days. Critical exceptions require approval from the Chief Information Security Officer delegate. Expired exceptions return the finding to Open status.'),
('P03', 'Asset Ownership Standard', 'Governance', 'Every production asset must map to a business service and an owning team in the asset inventory. Assets with no owner are escalated to the platform team after 14 days and reported in the monthly posture review. Ownership changes must be recorded within 5 business days.'),
('P04', 'Internet Exposure Policy', 'Exposure', 'Internet-facing assets must be registered, placed behind a web application firewall, and scanned weekly. Administrative interfaces must never be reachable from the internet. Any newly discovered internet-facing asset without a registered owner is treated as shadow IT and escalated within 2 business days.'),
('P05', 'Critical Service Prioritization Guide', 'Prioritization', 'Tier 1 services support customer-facing money movement or authentication and receive priority remediation capacity. When capacity is limited, order work by: known exploited findings on Tier 1 services, then internet-facing Critical findings, then remaining Critical and High findings by age.'),
('P06', 'Security Metrics Definitions', 'Reporting', 'Open Critical findings counts findings with status Open or In Progress and severity Critical. SLA breach rate is overdue open findings divided by all open findings. Mean age is the average number of days since a finding was opened, measured at the reporting date. Metrics exclude findings in Development environments unless stated.'),
('P07', 'Cloud Storage Configuration Standard', 'Configuration', 'Storage buckets must block public access by default, enforce encryption at rest, and log access. Public read access requires an approved exception. Buckets holding customer data must also have versioning and retention enabled.'),
('P08', 'Container Image Hygiene', 'Configuration', 'Container images must use a supported base image, be rebuilt at least monthly, and be scanned before deployment. Images with Critical findings may not be promoted to production. End-of-life base images must be replaced within 60 days.'),
('P09', 'Third-Party Component Management', 'Remediation', 'Open-source and vendor components must be tracked in an inventory. Components with a known exploited flaw must be upgraded or mitigated within 14 days. Teams own the update path for components they deploy.'),
('P10', 'Monthly Posture Review', 'Governance', 'Security leadership reviews posture monthly. The review covers open Critical and High findings, SLA breach rate by business service, aging findings over 90 days, unowned assets, and active exceptions. Owners of services with rising residual risk present a remediation plan.');
